   355	    private BigDecimal calcularAjustePagamento(DadosCompra dados, BigDecimal total) {
   356	        var forma = dados.getFormaPagamento();
   357	        var parcelas = dados.getParcelas() != null ? dados.getParcelas() : 1;
   358	
   359	        if (forma == DadosCompra.FormaPagamento.PIX && (dados.getCupom() == null || dados.getCupom().trim().isEmpty())) {
   360	            var desconto = total.multiply(new BigDecimal("0.05"));
   361	            return ArredondamentoUtil.arredondar(desconto.negate());
   362	        }
   363	
   364	        if (forma == DadosCompra.FormaPagamento.BOLETO) {
   365	            return ArredondamentoUtil.arredondar(new BigDecimal("3.49"));
   366	        }
   367	
   368	        if (forma == DadosCompra.FormaPagamento.CARTAO && parcelas > 3) {
   369	            var taxa = new BigDecimal("0.0199");
   370	            var expoente = parcelas;
   371	            var denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.add(taxa).pow(-expoente));
   372	            var jurosTotal = total.multiply(taxa).divide(denominador, 10, RoundingMode.HALF_EVEN);
   373	            jurosTotal = ArredondamentoUtil.arredondar(jurosTotal);
   374	            return jurosTotal;
   375	        }
   376	
   377	        return BigDecimal.ZERO;
   378	    }
