232	            .tipo(tipo)
233	            .pedidoId(pedido.getId())
234	            .situacao(Aviso.SituacaoAviso.NOVO)
235	            .criadoEm(Instant.now())
236	            .build();
237	        avisoRepository.save(aviso);
