    24	    public TransLogCotacao cotacao(String cep, BigDecimal pesoKg, String servico) {
    25	        try {
    26	            String url = config.getUrl() + "/cotacao?cep=" + cep + "&pesoKg=" + pesoKg + "&servico=" + servico;
    27	
    28	            log.debug("Chamando TransLog: {}", url);
    29	            var response = restTemplate.getForObject(url, TransLogCotacao.class);
    30	            return response;
    31	        } catch (HttpClientErrorException.NotFound e) {
    32	            log.debug("CEP não atendido pela TransLog");
    33	            return null;
    34	        } catch (ResourceAccessException e) {
    35	            log.warn("Timeout ao chamar TransLog");
